/**
 * Modern Glass Cockpit Telemetry Display Module
 * Renders an integrated G1000-style Primary Flight Display (PFD)
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let previousTelemetryData = {};
    let animationFrameId = null;
    let ctx = null;
    let canvas = null;

    // Animation and smoothing variables
    let smoothedValues = {
        airspeed: 0,
        altitude: 0,
        heading: 0,
        verticalSpeed: 0,
        pitch: 0,
        roll: 0
    };

    // Display constants based on modern glass cockpit design
    const DISPLAY = {
        WIDTH: 640,
        HEIGHT: 480,
        ATTITUDE_CENTER_X: 320,
        ATTITUDE_CENTER_Y: 240,
        ATTITUDE_WIDTH: 300,
        ATTITUDE_HEIGHT: 280,
        AIRSPEED_X: 20,
        AIRSPEED_WIDTH: 90,
        ALTITUDE_X: 530,
        ALTITUDE_WIDTH: 90,
        VS_X: 625,
        VS_WIDTH: 15,
        HEADING_Y: 420,
        HEADING_HEIGHT: 50
    };

    // Modern glass cockpit color scheme
    const COLORS = {
        SKY_BLUE: '#4169E1',
        SKY_LIGHT: '#87CEEB',
        EARTH_BROWN: '#8B4513',
        EARTH_DARK: '#2F1B14',
        HORIZON_WHITE: '#FFFFFF',
        GREEN_NORMAL: '#00FF88',
        GREEN_ARC: '#00AA00',
        YELLOW_CAUTION: '#FFFF00',
        YELLOW_ARC: '#FFAA00',
        RED_WARNING: '#FF4444',
        RED_LINE: '#FF0000',
        CYAN_INFO: '#00FFFF',
        MAGENTA_NAV: '#FF00FF',
        DISPLAY_BG: '#0a0a0a',
        TEXT_WHITE: '#FFFFFF',
        TEXT_GREEN: '#00FF88',
        TEXT_CYAN: '#00FFFF',
        TAPE_BG: 'rgba(0, 0, 0, 0.85)',
        TAPE_BORDER: '#333333',
        DIGITAL_BG: 'rgba(0, 0, 0, 0.95)',
        COMPASS_BG: 'rgba(0, 0, 0, 0.8)'
    };

    /**
     * Initialize Modern Glass Cockpit Display
     */
    function initialize() {
        console.log('Initializing Modern Glass Cockpit PFD...');

        // Get canvas and context
        canvas = document.getElementById('glass-pfd-display');
        if (!canvas) {
            console.error('Glass PFD canvas not found');
            return;
        }

        ctx = canvas.getContext('2d');
        if (!ctx) {
            console.error('Failed to get 2D context');
            return;
        }

        // Setup high DPI support
        setupHighDPI();

        // Setup event listeners
        setupEventListeners();

        // Start animation loop
        startAnimationLoop();

        console.log('Modern Glass Cockpit PFD initialized');
    }

    /**
     * Setup High DPI Support
     */
    function setupHighDPI() {
        const dpr = window.devicePixelRatio || 1;
        const rect = canvas.getBoundingClientRect();

        canvas.width = DISPLAY.WIDTH * dpr;
        canvas.height = DISPLAY.HEIGHT * dpr;
        ctx.scale(dpr, dpr);

        canvas.style.width = DISPLAY.WIDTH + 'px';
        canvas.style.height = DISPLAY.HEIGHT + 'px';
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateSmoothedValues();
            drawGlassCockpitPFD();
            updateStatusOverlays();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update Smoothed Values for Smooth Tape Animation
     */
    function updateSmoothedValues() {
        const smoothingFactor = 0.15; // Adjust for more/less smoothing

        // Calculate current values
        const groundSpeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        );
        const currentAirspeed = groundSpeed * 1.94384; // m/s to knots
        const currentAltitude = (telemetryData.alt_rel || 0) * 3.28084; // m to ft
        const currentHeading = telemetryData.hdg || 0;
        const currentVerticalSpeed = (telemetryData.vz || 0) * 196.85; // m/s to ft/min
        const currentPitch = telemetryData.pitch || 0;
        const currentRoll = telemetryData.roll || 0;

        // Apply exponential smoothing for fluid tape movement
        smoothedValues.airspeed = smoothedValues.airspeed + 
            (currentAirspeed - smoothedValues.airspeed) * smoothingFactor;
        smoothedValues.altitude = smoothedValues.altitude + 
            (currentAltitude - smoothedValues.altitude) * smoothingFactor;
        smoothedValues.verticalSpeed = smoothedValues.verticalSpeed + 
            (currentVerticalSpeed - smoothedValues.verticalSpeed) * smoothingFactor;
        smoothedValues.pitch = smoothedValues.pitch + 
            (currentPitch - smoothedValues.pitch) * smoothingFactor;
        smoothedValues.roll = smoothedValues.roll + 
            (currentRoll - smoothedValues.roll) * smoothingFactor;

        // Handle heading wraparound (0-360 degrees)
        let headingDiff = currentHeading - smoothedValues.heading;
        if (headingDiff > 180) headingDiff -= 360;
        if (headingDiff < -180) headingDiff += 360;
        smoothedValues.heading = smoothedValues.heading + headingDiff * smoothingFactor;
        if (smoothedValues.heading < 0) smoothedValues.heading += 360;
        if (smoothedValues.heading >= 360) smoothedValues.heading -= 360;
    }

    /**
     * Draw Complete Glass Cockpit Primary Flight Display
     */
    function drawGlassCockpitPFD() {
        // Clear display with modern background
        ctx.fillStyle = COLORS.DISPLAY_BG;
        ctx.fillRect(0, 0, DISPLAY.WIDTH, DISPLAY.HEIGHT);

        // Draw integrated components in proper order
        drawGarminAirspeedTape();
        drawRectangularAttitudeDisplay();
        drawGarminAltitudeTape();
        drawGarminVerticalSpeedIndicator();
        drawGarminHeadingTape();
        drawIntegratedReadouts();
        drawFlightDirector();
    }

    /**
     * Draw Modern Rectangular Attitude Display (G1000 style) - NO BLACK BORDERS
     */
    function drawRectangularAttitudeDisplay() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const width = DISPLAY.ATTITUDE_WIDTH;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Use smoothed attitude data for fluid movement
        const pitch = smoothedValues.pitch; // degrees
        const roll = smoothedValues.roll;   // degrees

        ctx.save();

        // NO CLIPPING - Let sky and ground extend to canvas edges!
        ctx.translate(centerX, centerY);
        ctx.rotate(roll * Math.PI / 180);

        // Calculate pitch offset (modern scaling: 4 pixels per degree for larger display)
        const pitchPixels = pitch * 4;

        // Draw sky extending to all edges (much larger to eliminate black borders)
        const skyGradient = ctx.createLinearGradient(0, -height * 2, 0, pitchPixels);
        skyGradient.addColorStop(0, COLORS.SKY_BLUE);
        skyGradient.addColorStop(1, COLORS.SKY_LIGHT);
        ctx.fillStyle = skyGradient;
        ctx.fillRect(-width * 1.5, -height * 2, width * 3, height * 2 + pitchPixels);

        // Draw ground extending to all edges (much larger to eliminate black borders)
        const groundGradient = ctx.createLinearGradient(0, pitchPixels, 0, height * 2);
        groundGradient.addColorStop(0, COLORS.EARTH_BROWN);
        groundGradient.addColorStop(1, COLORS.EARTH_DARK);
        ctx.fillStyle = groundGradient;
        ctx.fillRect(-width * 1.5, pitchPixels, width * 3, height * 3);

        // Draw horizon line (clean white line extending beyond visible area)
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-width * 1.5, pitchPixels);
        ctx.lineTo(width * 1.5, pitchPixels);
        ctx.stroke();

        // Draw modern pitch ladder
        drawModernPitchLadder(pitchPixels, width);

        ctx.restore();

        // Draw aircraft symbol (modern chevron style)
        drawModernAircraftSymbol(centerX, centerY);

        // NO BORDER RECTANGLE - Let the attitude display fill the entire area!
    }

    /**
     * Draw Modern Pitch Ladder (G1000 style)
     */
    function drawModernPitchLadder(pitchOffset, width) {
        const pitchAngles = [-30, -20, -15, -10, -5, 5, 10, 15, 20, 30];

        ctx.font = '14px Arial, sans-serif';
        ctx.textAlign = 'center';
        ctx.lineWidth = 2;
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;

        pitchAngles.forEach(angle => {
            const y = pitchOffset - (angle * 4); // 4 pixels per degree for larger display

            if (Math.abs(y) > 200) return; // Skip if outside visible area

            const isAboveHorizon = angle > 0;
            const isMajorLine = Math.abs(angle) % 10 === 0;
            const lineLength = isMajorLine ? 80 : 40;

            // Draw pitch line
            ctx.beginPath();
            ctx.moveTo(-lineLength/2, y);
            ctx.lineTo(lineLength/2, y);
            ctx.stroke();

            // Draw angle labels for major lines
            if (isMajorLine) {
                ctx.font = '13px Arial, sans-serif';
                ctx.fillText(Math.abs(angle).toString(), -lineLength/2 - 20, y + 4);
                ctx.fillText(Math.abs(angle).toString(), lineLength/2 + 20, y + 4);
            }

            // Draw modern chevron indicators
            if (Math.abs(angle) === 5 || Math.abs(angle) === 15) {
                const chevronSize = 8;
                ctx.beginPath();
                if (isAboveHorizon) {
                    // Upward chevron
                    ctx.moveTo(-chevronSize, y + chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y + chevronSize);
                } else {
                    // Downward chevron
                    ctx.moveTo(-chevronSize, y - chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y - chevronSize);
                }
                ctx.stroke();
            }
        });
    }

    /**
     * Draw Modern Aircraft Symbol (Clean Chevron Style) - Enhanced for G1000
     */
    function drawModernAircraftSymbol(centerX, centerY) {
        ctx.save();
        ctx.translate(centerX, centerY);

        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 3;

        // Center dot (larger for visibility)
        ctx.beginPath();
        ctx.arc(0, 0, 3, 0, Math.PI * 2);
        ctx.fill();

        // Modern wing bars (longer for larger display)
        ctx.beginPath();
        ctx.moveTo(-45, 0);
        ctx.lineTo(-10, 0);
        ctx.moveTo(45, 0);
        ctx.lineTo(10, 0);
        ctx.stroke();

        // Wing tips (subtle downward angle)
        ctx.beginPath();
        ctx.moveTo(-45, 0);
        ctx.lineTo(-45, 4);
        ctx.moveTo(45, 0);
        ctx.lineTo(45, 4);
        ctx.stroke();

        // Center reference triangle (G1000 style)
        ctx.beginPath();
        ctx.moveTo(0, -8);
        ctx.lineTo(-3, -3);
        ctx.lineTo(3, -3);
        ctx.closePath();
        ctx.fill();

        ctx.restore();
    }

    /**
     * Draw Garmin G1000-Style Airspeed Tape with Color Coding
     */
    function drawGarminAirspeedTape() {
        const x = DISPLAY.AIRSPEED_X;
        const width = DISPLAY.AIRSPEED_WIDTH;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Draw tape background
        ctx.fillStyle = COLORS.TAPE_BG;
        ctx.fillRect(x, centerY - height/2, width, height);

        // Use smoothed airspeed for fluid tape movement
        const airspeedKnots = smoothedValues.airspeed;

        // Garmin-style scaling: 4 pixels per knot
        const pixelsPerKnot = 4;

        // Draw color-coded speed ranges (V-speeds)
        drawSpeedColorBands(x, width, centerY, height, airspeedKnots, pixelsPerKnot);

        // Draw speed scale with Garmin-style tick marks
        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'right';
        ctx.lineWidth = 1;

        const minSpeed = Math.max(0, Math.floor((airspeedKnots - 50) / 10) * 10);
        const maxSpeed = Math.ceil((airspeedKnots + 50) / 10) * 10;

        for (let speed = minSpeed; speed <= maxSpeed; speed += 5) {
            const y = centerY + (airspeedKnots - speed) * pixelsPerKnot;

            if (y >= centerY - height/2 && y <= centerY + height/2) {
                const isMajorMark = speed % 10 === 0;
                const tickLength = isMajorMark ? 12 : 6;

                // Color-code tick marks based on speed ranges
                if (speed <= 40) {
                    ctx.strokeStyle = COLORS.RED_LINE;
                    ctx.fillStyle = COLORS.RED_LINE;
                } else if (speed <= 60) {
                    ctx.strokeStyle = COLORS.YELLOW_ARC;
                    ctx.fillStyle = COLORS.YELLOW_ARC;
                } else {
                    ctx.strokeStyle = COLORS.TEXT_WHITE;
                    ctx.fillStyle = COLORS.TEXT_WHITE;
                }

                // Draw tick mark
                ctx.beginPath();
                ctx.moveTo(x + width - tickLength, y);
                ctx.lineTo(x + width - 1, y);
                ctx.stroke();

                // Draw speed labels for major marks
                if (isMajorMark && speed >= 0) {
                    ctx.fillText(speed.toString(), x + width - 16, y + 4);
                }
            }
        }

        // Draw current airspeed digital readout (Garmin style)
        const readoutHeight = 24;
        const readoutWidth = 50;
        const readoutY = centerY - readoutHeight/2;
        const readoutX = x + width - readoutWidth - 2;

        // Digital readout background
        ctx.fillStyle = COLORS.DIGITAL_BG;
        ctx.fillRect(readoutX, readoutY, readoutWidth, readoutHeight);

        // Digital readout border with speed-based color coding
        let borderColor = COLORS.TEXT_WHITE;
        if (airspeedKnots <= 40) {
            borderColor = COLORS.RED_LINE;
        } else if (airspeedKnots <= 60) {
            borderColor = COLORS.YELLOW_ARC;
        } else if (airspeedKnots >= 120) {
            borderColor = COLORS.RED_LINE;
        }

        ctx.strokeStyle = borderColor;
        ctx.lineWidth = 2;
        ctx.strokeRect(readoutX, readoutY, readoutWidth, readoutHeight);

        // Digital readout text
        ctx.fillStyle = borderColor;
        ctx.textAlign = 'center';
        ctx.font = 'bold 16px Arial, sans-serif';
        ctx.fillText(Math.round(airspeedKnots).toString(), readoutX + readoutWidth/2, centerY + 5);

        // Draw trend arrow if speed is changing rapidly
        drawSpeedTrendArrow(readoutX + readoutWidth + 5, centerY, airspeedKnots);

        // Draw tape border
        ctx.strokeStyle = COLORS.TAPE_BORDER;
        ctx.lineWidth = 2;
        ctx.strokeRect(x, centerY - height/2, width, height);
    }

    /**
     * Draw Speed Color Bands (V-speed ranges)
     */
    function drawSpeedColorBands(x, width, centerY, height, currentSpeed, pixelsPerKnot) {
        const bandWidth = 8;
        const bandX = x + 2;

        // Green arc (normal operating range): 45-80 knots
        const greenStart = centerY + (currentSpeed - 80) * pixelsPerKnot;
        const greenEnd = centerY + (currentSpeed - 45) * pixelsPerKnot;

        if (greenEnd >= centerY - height/2 && greenStart <= centerY + height/2) {
            ctx.fillStyle = COLORS.GREEN_ARC;
            const clampedStart = Math.max(centerY - height/2, greenStart);
            const clampedEnd = Math.min(centerY + height/2, greenEnd);
            ctx.fillRect(bandX, clampedStart, bandWidth, clampedEnd - clampedStart);
        }

        // Yellow arc (caution range): 80-100 knots
        const yellowStart = centerY + (currentSpeed - 100) * pixelsPerKnot;
        const yellowEnd = centerY + (currentSpeed - 80) * pixelsPerKnot;

        if (yellowEnd >= centerY - height/2 && yellowStart <= centerY + height/2) {
            ctx.fillStyle = COLORS.YELLOW_ARC;
            const clampedStart = Math.max(centerY - height/2, yellowStart);
            const clampedEnd = Math.min(centerY + height/2, yellowEnd);
            ctx.fillRect(bandX, clampedStart, bandWidth, clampedEnd - clampedStart);
        }

        // Red line (maximum speed): 120 knots
        const redLineY = centerY + (currentSpeed - 120) * pixelsPerKnot;
        if (redLineY >= centerY - height/2 && redLineY <= centerY + height/2) {
            ctx.strokeStyle = COLORS.RED_LINE;
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(bandX, redLineY);
            ctx.lineTo(bandX + bandWidth, redLineY);
            ctx.stroke();
        }
    }

    /**
     * Draw Speed Trend Arrow
     */
    function drawSpeedTrendArrow(x, y, currentSpeed) {
        // This would show speed trend - for now, just a placeholder
        // In a real implementation, we'd track speed changes over time
        const speedTrend = 0; // Placeholder for speed trend calculation

        if (Math.abs(speedTrend) > 2) {
            ctx.strokeStyle = COLORS.CYAN_INFO;
            ctx.lineWidth = 2;
            ctx.beginPath();

            if (speedTrend > 0) {
                // Up arrow for increasing speed
                ctx.moveTo(x, y);
                ctx.lineTo(x + 8, y - 8);
                ctx.moveTo(x + 5, y - 5);
                ctx.lineTo(x + 8, y - 8);
                ctx.lineTo(x + 11, y - 5);
            } else {
                // Down arrow for decreasing speed
                ctx.moveTo(x, y);
                ctx.lineTo(x + 8, y + 8);
                ctx.moveTo(x + 5, y + 5);
                ctx.lineTo(x + 8, y + 8);
                ctx.lineTo(x + 11, y + 5);
            }
            ctx.stroke();
        }
    }

    /**
     * Draw Garmin G1000-Style Altitude Tape
     */
    function drawGarminAltitudeTape() {
        const x = DISPLAY.ALTITUDE_X;
        const width = DISPLAY.ALTITUDE_WIDTH;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Draw tape background
        ctx.fillStyle = COLORS.TAPE_BG;
        ctx.fillRect(x, centerY - height/2, width, height);

        // Use smoothed altitude for fluid tape movement
        const altitudeFeet = smoothedValues.altitude;

        // Garmin-style scaling: 1 pixel per foot
        const pixelsPerFoot = 1.0;

        // Draw altitude scale with proper Garmin tick marks
        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'left';
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;

        const minAlt = Math.floor((altitudeFeet - 150) / 20) * 20;
        const maxAlt = Math.ceil((altitudeFeet + 150) / 20) * 20;

        for (let alt = minAlt; alt <= maxAlt; alt += 20) {
            const y = centerY + (altitudeFeet - alt) * pixelsPerFoot;

            if (y >= centerY - height/2 && y <= centerY + height/2) {
                const isMajorMark = alt % 100 === 0;
                const tickLength = isMajorMark ? 12 : 6;

                // Draw tick mark
                ctx.beginPath();
                ctx.moveTo(x + 1, y);
                ctx.lineTo(x + 1 + tickLength, y);
                ctx.stroke();

                // Draw altitude labels for major marks
                if (isMajorMark) {
                    ctx.fillText(alt.toString(), x + 16, y + 4);
                } else if (alt % 50 === 0) {
                    // Draw minor labels for 50-foot marks
                    ctx.font = '10px Arial, sans-serif';
                    ctx.fillText(alt.toString(), x + 16, y + 3);
                    ctx.font = '12px Arial, sans-serif';
                }
            }
        }

        // Draw current altitude digital readout (Garmin style)
        const readoutHeight = 28;
        const readoutWidth = 60;
        const readoutY = centerY - readoutHeight/2;
        const readoutX = x + 3;

        // Digital readout background
        ctx.fillStyle = COLORS.DIGITAL_BG;
        ctx.fillRect(readoutX, readoutY, readoutWidth, readoutHeight);

        // Digital readout border (cyan for altitude)
        ctx.strokeStyle = COLORS.CYAN_INFO;
        ctx.lineWidth = 2;
        ctx.strokeRect(readoutX, readoutY, readoutWidth, readoutHeight);

        // Digital readout text with proper formatting
        ctx.fillStyle = COLORS.CYAN_INFO;
        ctx.textAlign = 'center';
        ctx.font = 'bold 16px Arial, sans-serif';

        // Format altitude to show appropriate precision
        let altText;
        if (altitudeFeet < 10000) {
            altText = Math.round(altitudeFeet).toString();
        } else {
            // Show in thousands for high altitudes
            altText = (altitudeFeet / 1000).toFixed(1) + 'K';
        }

        ctx.fillText(altText, readoutX + readoutWidth/2, centerY + 5);

        // Draw altitude trend arrow
        drawAltitudeTrendArrow(readoutX + readoutWidth + 5, centerY, altitudeFeet);

        // Draw ground reference line if near ground
        if (altitudeFeet <= 200) {
            const groundY = centerY + (altitudeFeet - 0) * pixelsPerFoot;
            if (groundY <= centerY + height/2) {
                ctx.strokeStyle = COLORS.EARTH_BROWN;
                ctx.lineWidth = 4;
                ctx.beginPath();
                ctx.moveTo(x, groundY);
                ctx.lineTo(x + width, groundY);
                ctx.stroke();

                // Add "GND" label
                ctx.fillStyle = COLORS.EARTH_BROWN;
                ctx.font = 'bold 10px Arial, sans-serif';
                ctx.fillText('GND', x + width - 25, groundY - 5);
            }
        }

        // Draw tape border
        ctx.strokeStyle = COLORS.TAPE_BORDER;
        ctx.lineWidth = 2;
        ctx.strokeRect(x, centerY - height/2, width, height);
    }

    /**
     * Draw Altitude Trend Arrow
     */
    function drawAltitudeTrendArrow(x, y, currentAltitude) {
        // Use smoothed vertical speed for trend arrow
        const verticalSpeed = smoothedValues.verticalSpeed;

        if (Math.abs(verticalSpeed) > 100) {
            ctx.strokeStyle = COLORS.CYAN_INFO;
            ctx.lineWidth = 2;
            ctx.beginPath();

            if (verticalSpeed > 0) {
                // Up arrow for climbing
                ctx.moveTo(x, y);
                ctx.lineTo(x + 8, y - 8);
                ctx.moveTo(x + 5, y - 5);
                ctx.lineTo(x + 8, y - 8);
                ctx.lineTo(x + 11, y - 5);
            } else {
                // Down arrow for descending
                ctx.moveTo(x, y);
                ctx.lineTo(x + 8, y + 8);
                ctx.moveTo(x + 5, y + 5);
                ctx.lineTo(x + 8, y + 8);
                ctx.lineTo(x + 11, y + 5);
            }
            ctx.stroke();
        }
    }

    /**
     * Draw Garmin G1000-Style Vertical Speed Indicator
     */
    function drawGarminVerticalSpeedIndicator() {
        const x = DISPLAY.VS_X;
        const width = DISPLAY.VS_WIDTH;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = DISPLAY.ATTITUDE_HEIGHT;

        // Use smoothed vertical speed for fluid indicator movement
        const verticalSpeed = smoothedValues.verticalSpeed;

        // Draw VS indicator background (thin vertical strip)
        ctx.fillStyle = COLORS.TAPE_BG;
        ctx.fillRect(x, centerY - height/2, width, height);

        // Draw scale markings
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.font = '10px Arial, sans-serif';
        ctx.textAlign = 'right';

        // VS scale: -2000 to +2000 fpm
        const maxVS = 2000;
        const pixelsPerFPM = height / (2 * maxVS);

        // Draw tick marks and labels
        const vsMarks = [-2000, -1000, -500, 0, 500, 1000, 2000];
        vsMarks.forEach(vs => {
            const y = centerY - (vs * pixelsPerFPM);

            if (y >= centerY - height/2 && y <= centerY + height/2) {
                const tickLength = (vs === 0) ? 8 : 4;

                // Draw tick mark
                ctx.beginPath();
                ctx.moveTo(x, y);
                ctx.lineTo(x + tickLength, y);
                ctx.stroke();

                // Draw labels for major marks
                if (Math.abs(vs) >= 500 || vs === 0) {
                    const label = vs === 0 ? '0' : (Math.abs(vs) >= 1000 ? (vs/1000).toString() : (vs/100).toString());
                    ctx.fillText(label, x - 2, y + 3);
                }
            }
        });

        // Draw current VS indicator
        const currentVSY = centerY - (verticalSpeed * pixelsPerFPM);

        // Clamp to visible area
        if (currentVSY >= centerY - height/2 && currentVSY <= centerY + height/2) {
            // Draw VS pointer (triangle)
            ctx.fillStyle = COLORS.GREEN_NORMAL;
            ctx.strokeStyle = COLORS.GREEN_NORMAL;
            ctx.lineWidth = 2;

            ctx.beginPath();
            if (verticalSpeed > 50) {
                // Climb indicator (up triangle)
                ctx.moveTo(x + width/2, currentVSY - 4);
                ctx.lineTo(x + 2, currentVSY + 2);
                ctx.lineTo(x + width - 2, currentVSY + 2);
            } else if (verticalSpeed < -50) {
                // Descent indicator (down triangle)
                ctx.moveTo(x + width/2, currentVSY + 4);
                ctx.lineTo(x + 2, currentVSY - 2);
                ctx.lineTo(x + width - 2, currentVSY - 2);
            } else {
                // Minimal VS - small diamond
                ctx.moveTo(x + width/2, currentVSY - 2);
                ctx.lineTo(x + 2, currentVSY);
                ctx.lineTo(x + width/2, currentVSY + 2);
                ctx.lineTo(x + width - 2, currentVSY);
            }
            ctx.closePath();
            ctx.fill();
        }

        // Draw zero line emphasis
        const zeroY = centerY;
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, zeroY);
        ctx.lineTo(x + width, zeroY);
        ctx.stroke();

        // Draw VS border
        ctx.strokeStyle = COLORS.TAPE_BORDER;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);

        // Display numeric VS readout if significant
        if (Math.abs(verticalSpeed) > 100) {
            const readoutX = x - 35;
            const readoutY = centerY - 8;

            ctx.fillStyle = COLORS.DIGITAL_BG;
            ctx.fillRect(readoutX, readoutY, 30, 16);

            ctx.strokeStyle = COLORS.GREEN_NORMAL;
            ctx.lineWidth = 1;
            ctx.strokeRect(readoutX, readoutY, 30, 16);

            ctx.fillStyle = COLORS.GREEN_NORMAL;
            ctx.textAlign = 'center';
            ctx.font = '10px Arial, sans-serif';
            const vsText = Math.round(verticalSpeed/100) + '00';
            ctx.fillText(vsText, readoutX + 15, centerY + 2);
        }
    }

    /**
     * Draw Garmin G1000-Style Heading Tape
     */
    function drawGarminHeadingTape() {
        const y = DISPLAY.HEADING_Y;
        const height = DISPLAY.HEADING_HEIGHT;
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const width = DISPLAY.WIDTH - 40; // Leave margins

        // Use smoothed heading for fluid tape movement
        const heading = smoothedValues.heading;

        // Draw tape background
        ctx.fillStyle = COLORS.COMPASS_BG;
        ctx.fillRect(20, y, width, height);

        // Garmin-style scaling: 2 pixels per degree
        const pixelsPerDegree = 2;
        const tapeCenter = centerX;

        // Draw heading scale
        ctx.font = '12px Arial, sans-serif';
        ctx.textAlign = 'center';
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;

        // Calculate heading range to display
        const headingRange = 60; // Show 60 degrees each side
        const minHeading = heading - headingRange;
        const maxHeading = heading + headingRange;

        for (let hdg = Math.floor(minHeading/10)*10; hdg <= maxHeading; hdg += 10) {
            let normalizedHdg = hdg;
            while (normalizedHdg < 0) normalizedHdg += 360;
            while (normalizedHdg >= 360) normalizedHdg -= 360;

            const x = tapeCenter + (hdg - heading) * pixelsPerDegree;

            if (x >= 20 && x <= width + 20) {
                const isMajorMark = normalizedHdg % 30 === 0;
                const tickLength = isMajorMark ? 20 : 10;

                // Draw tick mark
                ctx.beginPath();
                ctx.moveTo(x, y + height - tickLength);
                ctx.lineTo(x, y + height - 1);
                ctx.stroke();

                // Draw heading labels
                if (isMajorMark) {
                    let label;
                    switch (normalizedHdg) {
                        case 0: label = 'N'; break;
                        case 30: label = 'NE'; break;
                        case 60: label = '6'; break;
                        case 90: label = 'E'; break;
                        case 120: label = '12'; break;
                        case 150: label = 'SE'; break;
                        case 180: label = 'S'; break;
                        case 210: label = 'SW'; break;
                        case 240: label = '24'; break;
                        case 270: label = 'W'; break;
                        case 300: label = '30'; break;
                        case 330: label = 'NW'; break;
                        default: label = (normalizedHdg/10).toString();
                    }

                    ctx.fillText(label, x, y + height - 25);
                } else {
                    // Minor marks for every 10 degrees
                    ctx.font = '10px Arial, sans-serif';
                    ctx.fillText((normalizedHdg/10).toString(), x, y + height - 25);
                    ctx.font = '12px Arial, sans-serif';
                }
            }
        }

        // Draw current heading indicator (lubber line)
        ctx.strokeStyle = COLORS.MAGENTA_NAV;
        ctx.fillStyle = COLORS.MAGENTA_NAV;
        ctx.lineWidth = 3;

        // Draw heading bug (triangle pointing down)
        ctx.beginPath();
        ctx.moveTo(centerX, y + height);
        ctx.lineTo(centerX - 8, y + height - 12);
        ctx.lineTo(centerX + 8, y + height - 12);
        ctx.closePath();
        ctx.fill();

        // Draw vertical reference line
        ctx.beginPath();
        ctx.moveTo(centerX, y);
        ctx.lineTo(centerX, y + height - 12);
        ctx.stroke();

        // Draw current heading digital readout
        const readoutWidth = 50;
        const readoutHeight = 20;
        const readoutX = centerX - readoutWidth/2;
        const readoutY = y + 5;

        ctx.fillStyle = COLORS.DIGITAL_BG;
        ctx.fillRect(readoutX, readoutY, readoutWidth, readoutHeight);

        ctx.strokeStyle = COLORS.MAGENTA_NAV;
        ctx.lineWidth = 2;
        ctx.strokeRect(readoutX, readoutY, readoutWidth, readoutHeight);

        ctx.fillStyle = COLORS.MAGENTA_NAV;
        ctx.textAlign = 'center';
        ctx.font = 'bold 14px Arial, sans-serif';
        ctx.fillText(Math.round(heading).toString().padStart(3, '0') + '°', centerX, readoutY + 14);

        // Draw tape border
        ctx.strokeStyle = COLORS.TAPE_BORDER;
        ctx.lineWidth = 2;
        ctx.strokeRect(20, y, width, height);
    }

    /**
     * Draw Integrated Digital Readouts
     */
    function drawIntegratedReadouts() {
        // Additional integrated readouts can be added here
        // The main tape displays now handle most of the primary flight data

        // Draw any supplementary information that doesn't fit on the tapes
        // For example: radio altimeter, flight director bars, etc.
    }

    /**
     * Draw Flight Director (Command Bars)
     */
    function drawFlightDirector() {
        // This would integrate flight director command bars
        // For now, we'll draw a simple cross-hair reference
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;

        ctx.strokeStyle = COLORS.MAGENTA_NAV;
        ctx.lineWidth = 2;

        // Horizontal command bar placeholder
        ctx.beginPath();
        ctx.moveTo(centerX - 15, centerY);
        ctx.lineTo(centerX + 15, centerY);
        ctx.stroke();

        // Vertical command bar placeholder
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - 15);
        ctx.lineTo(centerX, centerY + 15);
        ctx.stroke();
    }

    /**
     * Update Status Overlays
     */
    function updateStatusOverlays() {
        // Update flight mode display
        const flightModeDisplay = document.getElementById('flight-mode-display');
        if (flightModeDisplay) {
            const mode = telemetryData.mode || 'UNKNOWN';
            const modeAbbreviations = {
                'STABILIZE': 'STAB',
                'ALT_HOLD': 'ALT',
                'POS_HOLD': 'POS',
                'LOITER': 'LOIT',
                'GUIDED': 'GUID',
                'RTL': 'RTL',
                'LAND': 'LAND',
                'AUTO': 'AUTO',
                'BRAKE': 'BRK'
            };
            flightModeDisplay.textContent = modeAbbreviations[mode] || mode;
        }

        // Update armed status
        const armedIndicator = document.getElementById('armed-status-indicator');
        if (armedIndicator) {
            const armed = telemetryData.armed;
            armedIndicator.textContent = armed ? 'ARMED' : 'SAFE';
            armedIndicator.className = armed ? 'armed-indicator armed' : 'armed-indicator';
        }

        // Update battery voltage
        const batteryVoltage = document.getElementById('battery-voltage');
        if (batteryVoltage) {
            const voltage = telemetryData.battery_voltage || 0;
            batteryVoltage.textContent = voltage.toFixed(1) + 'V';

            // Color coding
            if (voltage > 12.6) {
                batteryVoltage.style.color = COLORS.GREEN_NORMAL;
            } else if (voltage > 11.1) {
                batteryVoltage.style.color = COLORS.YELLOW_CAUTION;
            } else {
                batteryVoltage.style.color = COLORS.RED_WARNING;
            }
        }

        // Update current draw
        const currentDraw = document.getElementById('current-draw');
        if (currentDraw) {
            const current = telemetryData.current || 0;
            currentDraw.textContent = current.toFixed(1) + 'A';
            currentDraw.style.color = current > 20 ? COLORS.YELLOW_CAUTION : COLORS.GREEN_NORMAL;
        }

        // Update GPS status
        const gpsStatus = document.getElementById('gps-status');
        if (gpsStatus) {
            const fixType = telemetryData.gps_fix_type || 0;
            const sats = telemetryData.satellites_visible || 0;
            const fixTypes = ['NO GPS', 'NO FIX', '2D', '3D', 'DGPS', 'RTK FL', 'RTK FX'];
            const fixName = fixTypes[fixType] || 'UNK';

            gpsStatus.textContent = `${fixName} ${sats}S`;

            if (fixType >= 3) {
                gpsStatus.style.color = COLORS.GREEN_NORMAL;
            } else if (fixType >= 2) {
                gpsStatus.style.color = COLORS.YELLOW_CAUTION;
            } else {
                gpsStatus.style.color = COLORS.RED_WARNING;
            }
        }

        // Update position display
        const positionDisplay = document.getElementById('position-display');
        if (positionDisplay) {
            const lat = telemetryData.lat || 0;
            const lon = telemetryData.lon || 0;

            if (lat !== 0 && lon !== 0) {
                const latFormatted = Math.abs(lat).toFixed(6) + (lat >= 0 ? 'N' : 'S');
                const lonFormatted = Math.abs(lon).toFixed(6) + (lon >= 0 ? 'E' : 'W');
                positionDisplay.textContent = `${latFormatted} ${lonFormatted}`;
            } else {
                positionDisplay.textContent = 'LAT -- LON --';
            }
        }

        // Update ground speed
        const groundSpeedDisplay = document.getElementById('ground-speed');
        if (groundSpeedDisplay) {
            const groundSpeed = Math.sqrt(
                Math.pow(telemetryData.vx || 0, 2) + 
                Math.pow(telemetryData.vy || 0, 2)
            );
            const groundSpeedKnots = groundSpeed * 1.94384;
            groundSpeedDisplay.textContent = groundSpeedKnots.toFixed(1);
        }

        // Update vertical speed
        const verticalSpeedDisplay = document.getElementById('vertical-speed');
        if (verticalSpeedDisplay) {
            const verticalSpeed = (telemetryData.vz || 0) * 196.85; // m/s to ft/min
            verticalSpeedDisplay.textContent = Math.round(verticalSpeed).toString();
        }

        // Update G1000-style flight data
        updateG1000FlightData();
    }

    /**
     * Update G1000-Style Flight Data Display
     */
    function updateG1000FlightData() {
        // Update heading display
        const headingDisplay = document.getElementById('heading-display');
        if (headingDisplay) {
            const heading = telemetryData.hdg || 0;
            headingDisplay.textContent = Math.round(heading).toString().padStart(3, '0') + '°';
        }

        // Update track display (same as heading for now)
        const trackDisplay = document.getElementById('track-display');
        if (trackDisplay) {
            const heading = telemetryData.hdg || 0;
            trackDisplay.textContent = Math.round(heading).toString().padStart(3, '0') + '°';
        }

        // Update flight time
        const flightTimeDisplay = document.getElementById('flight-time');
        if (flightTimeDisplay) {
            const now = new Date();
            const minutes = now.getMinutes().toString().padStart(2, '0');
            const seconds = now.getSeconds().toString().padStart(2, '0');
            flightTimeDisplay.textContent = `${minutes}:${seconds}`;
        }

        // Update temperature (placeholder)
        const temperatureDisplay = document.getElementById('temperature-display');
        if (temperatureDisplay) {
            temperatureDisplay.textContent = '20°C';
        }
    }

    /**
     * Handle Telemetry Update
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    /**
     * Handle Connection Change
     */
    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            telemetryData = {};
        }
    }

    /**
     * Handle Resize
     */
    function handleResize() {
        setTimeout(() => {
            setupHighDPI();
        }, 100);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,
        getTelemetryData: () => ({ ...telemetryData }),
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

